const s=new IntersectionObserver(e=>e.forEach(t=>{t.isIntersecting&&t.target.classList.add("visible")}),{threshold:.08});document.querySelectorAll(".reveal").forEach(e=>s.observe(e));document.querySelectorAll(".glow-card").forEach(e=>{e.addEventListener("mousemove",t=>{const n=e.getBoundingClientRect();e.style.setProperty("--mouse-x",`${(t.clientX-n.left)/n.width*100}%`),e.style.setProperty("--mouse-y",`${(t.clientY-n.top)/n.height*100}%`)})});const o=document.getElementById("nav-toggle"),l=document.getElementById("mobile-menu"),c=document.getElementById("icon-open"),i=document.getElementById("icon-close");o.addEventListener("click",()=>{const e=l.classList.toggle("hidden")===!1;o.setAttribute("aria-expanded",String(e)),c.classList.toggle("hidden",e),i.classList.toggle("hidden",!e)});
